parameters.jsCode:
return $input.all().map((item) => {
  const fileName = String(item.json.fileName || '');
  const mimeType = String(item.json.mimeType || '').toLowerCase();
  if (!fileName.toLowerCase().endsWith('.csv') && !['text/csv', 'application/csv'].includes(mimeType)) {
    throw new Error('Unsupported statement format: this workflow accepts CSV files only');
  }
  return item;
});

parameters.inputSchema:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "rows": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "trackName": { "type": "string", "description": "Track title copied from the statement row" },
          "plays": { "type": "integer", "minimum": 0, "description": "Non-negative whole-number plays copied from the statement row; do not calculate or change" },
          "territory": { "type": "string", "description": "Territory copied from the statement row" },
          "tier": { "type": ["string", "null"], "description": "Source tier, or null when the source has no tier" },
          "actualPayout": { "type": "string", "description": "Reported payout preserved exactly as a decimal string" }
        },
        "required": ["trackName", "plays", "territory", "actualPayout"]
      }
    }
  },
  "required": ["rows"]
}

