const extracted = $input.all();
const sourceRows = $('Extract From File').all();
function reject(message) {
  throw new Error('AI output rejected: ' + message);
}
if (extracted.length !== sourceRows.length) reject('AI row count does not match CSV source row count');
const allowedRowFields = new Set(['trackName', 'plays', 'territory', 'tier', 'actualPayout']);
function sourceValue(row, aliases, field) {
  for (const alias of aliases) {
    const value = row[alias];
    if (value !== undefined && value !== null && String(value).trim() !== '') return String(value);
  }
  reject('CSV row is missing ' + field);
}
for (let index = 0; index < extracted.length; index++) {
  const output = extracted[index]?.json?.output;
  const source = sourceRows[index]?.json;
  if (!output || typeof output !== 'object' || Array.isArray(output)) reject('structured output is missing for CSV row ' + (index + 1));
  if (Object.keys(output).some((field) => field !== 'rows')) reject('output contains fields outside the canonical rows schema');
  if (!Array.isArray(output.rows)) reject('rows must be an array for CSV row ' + (index + 1));
  if (output.rows.length !== 1) reject('each AI output must contain exactly one row for its CSV source row');
  const row = output.rows[0];
  if (!row || typeof row !== 'object' || Array.isArray(row)) reject('rows[' + index + '] must be an object');
  const unsupportedField = Object.keys(row).find((field) => !allowedRowFields.has(field));
  if (unsupportedField) reject('row contains unsupported field ' + unsupportedField);
  if (typeof row.trackName !== 'string' || !row.trackName.trim()) reject('trackName is required for CSV row ' + (index + 1));
  if (typeof row.territory !== 'string' || !row.territory.trim()) reject('territory is required for CSV row ' + (index + 1));
  if (typeof row.plays !== 'number' || !Number.isInteger(row.plays) || row.plays < 0) reject('plays must be a non-negative integer for CSV row ' + (index + 1));
  if (typeof row.actualPayout !== 'string' || !/^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/.test(row.actualPayout)) reject('actualPayout must be a non-negative decimal string for CSV row ' + (index + 1));
  if (!source || typeof source !== 'object' || Array.isArray(source)) reject('CSV source row ' + (index + 1) + ' is missing');
  const originalUnits = sourceValue(source, ['eligibleUnits', 'eligible_units', 'plays', 'streams', 'units'], 'plays').trim();
  if (!/^\d+$/.test(originalUnits)) reject('CSV plays is not a non-negative integer for row ' + (index + 1));
  if (BigInt(row.plays) !== BigInt(originalUnits)) reject('plays does not match the CSV source for row ' + (index + 1));
  const originalPayout = sourceValue(source, ['actualPayout', 'actual_payout', 'payout', 'royalty'], 'actualPayout');
  if (!/^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/.test(originalPayout)) reject('CSV actualPayout is not a valid decimal string for row ' + (index + 1));
  if (row.actualPayout !== originalPayout) reject('actualPayout does not exactly match the CSV source for row ' + (index + 1));
  const originalTrack = sourceValue(source, ['trackName', 'track_name', 'track', 'title'], 'trackName').trim();
  if (row.trackName.trim() !== originalTrack) reject('trackName does not match the CSV source for row ' + (index + 1));
  const originalTerritory = sourceValue(source, ['territory', 'country', 'countryCode'], 'territory').trim().toUpperCase();
  if (row.territory.trim().toUpperCase() !== originalTerritory) reject('territory does not match the CSV source for row ' + (index + 1));
  const originalTier = ['tier', 'rateTier'].map((field) => source[field]).find((value) => value !== undefined && value !== null && String(value).trim() !== '');
  if (row.tier !== undefined && row.tier !== null && typeof row.tier !== 'string') reject('tier must be a string or null for CSV row ' + (index + 1));
  if (typeof row.tier === 'string' && row.tier.trim() && (!originalTier || row.tier.trim() !== String(originalTier).trim())) reject('tier does not match the CSV source for row ' + (index + 1));
}
return extracted;

const extracted = $input.all();
const sourceRows = $('Extract From File').all();
const metadataItems = $('Prepare Statement Metadata').all();
if (extracted.length !== sourceRows.length) throw new Error('Validated AI row count does not match CSV row count');
const statements = new Map();
function requiredText(value, field) {
  if (typeof value !== 'string' || value.trim() === '') throw new Error('CSV row is missing ' + field);
  return value.trim();
}
function sourceValue(row, aliases, field) {
  for (const alias of aliases) {
    const value = row[alias];
    if (value !== undefined && value !== null && String(value).trim() !== '') return String(value);
  }
  throw new Error('CSV row is missing ' + field);
}
for (let index = 0; index < extracted.length; index++) {
  const sourceRow = sourceRows[index];
  const source = sourceRow.json;
  const pairedItem = Array.isArray(sourceRow.pairedItem) ? sourceRow.pairedItem[0]?.item : sourceRow.pairedItem?.item;
  const metadata = metadataItems[pairedItem ?? 0]?.json;
  if (!metadata || !source || typeof source !== 'object') throw new Error('Could not match source CSV row to statement metadata');
  const key = String(metadata.sourceFileId || '');
  if (!key) throw new Error('Google Drive source file ID is missing');
  const platform = String(metadata.platform || '').trim();
  const statementPeriod = String(metadata.statementPeriod || '').trim();
  if (!platform) throw new Error('Set ROYALTYGUARD_PLATFORM or provide Drive appProperties.platform');
  if (!statementPeriod) throw new Error('Set ROYALTYGUARD_STATEMENT_PERIOD or provide Drive appProperties.statementPeriod');
  let statement = statements.get(key);
  if (!statement) {
    statement = {
      platform,
      statementPeriod,
      rows: [],
      sourceMetadata: {
        sourceFileId: metadata.sourceFileId,
        fileName: metadata.fileName,
        mimeType: metadata.mimeType,
        sourceLocation: metadata.sourceLocation,
        createdTime: metadata.createdTime || undefined,
        modifiedTime: metadata.modifiedTime || undefined
      }
    };
    statements.set(key, statement);
  }
  const eligibleUnits = requiredText(sourceValue(source, ['eligibleUnits', 'eligible_units', 'plays', 'streams', 'units'], 'plays'), 'eligibleUnits');
  if (!/^\d+$/.test(eligibleUnits)) throw new Error('eligibleUnits must be a non-negative whole-number string');
  const actualPayout = sourceValue(source, ['actualPayout', 'actual_payout', 'payout', 'royalty'], 'actualPayout');
  if (!/^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/.test(actualPayout)) throw new Error('actualPayout must be a non-negative decimal string with at most two fractional digits');
  const tierValue = ['tier', 'rateTier'].map((field) => source[field]).find((value) => value !== undefined && value !== null && String(value).trim() !== '');
  statement.rows.push({
    trackName: requiredText(sourceValue(source, ['trackName', 'track_name', 'track', 'title'], 'trackName'), 'trackName'),
    eligibleUnits,
    territory: requiredText(sourceValue(source, ['territory', 'country', 'countryCode'], 'territory'), 'territory').toUpperCase(),
    tier: tierValue === undefined ? null : String(tierValue).trim(),
    actualPayout
  });
}
return Array.from(statements.values(), (statement) => ({ json: statement }));

const submitted = $input.all();
const statements = $('Prepare Canonical Data').all();
if (submitted.length !== statements.length) throw new Error('Backend statement acknowledgement count does not match input');
const output = [];
for (let index = 0; index < statements.length; index++) {
  const statement = statements[index].json;
  const statementId = submitted[index].json.data?.statementId;
  if (!Number.isSafeInteger(Number(statementId)) || Number(statementId) < 1) throw new Error('Backend did not return a valid statementId');
  for (const row of statement.rows) {
    output.push({ json: { statementId: Number(statementId), platform: statement.platform, statementPeriod: statement.statementPeriod, sourceMetadata: statement.sourceMetadata, ...row } });
  }
}
return output;

const rateResponses = $input.all();
const rows = $('Expand Rows For Rate Retrieval').all();
if (rateResponses.length !== rows.length) throw new Error('Rate response count does not match royalty row count');
function parseScaledDecimal(value, scale, field) {
  const text = String(value);
  const match = /^(0|[1-9]\d*)(?:\.(\d+))?$/.exec(text);
  if (!match) throw new Error(field + ' must be a non-negative decimal string');
  const fraction = match[2] || '';
  if (fraction.length > scale && /[^0]/.test(fraction.slice(scale))) throw new Error(field + ' exceeds supported precision');
  return BigInt(match[1]) * (10n ** BigInt(scale)) + BigInt(fraction.slice(0, scale).padEnd(scale, '0') || '0');
}
function formatScaled(value, scale) {
  const negative = value < 0n;
  const absolute = negative ? -value : value;
  const whole = absolute / (10n ** BigInt(scale));
  const fraction = (absolute % (10n ** BigInt(scale))).toString().padStart(scale, '0');
  return (negative ? '-' : '') + whole.toString() + '.' + fraction;
}
const thresholdText = String($env.ROYALTYGUARD_DISCREPANCY_THRESHOLD || '0.00');
const thresholdCents = parseScaledDecimal(thresholdText, 2, 'threshold');
return rows.map((entry, index) => {
  const row = entry.json;
  const response = rateResponses[index].json;
  const rateValue = response.rate ?? response.data?.rate;
  if (rateValue === undefined || rateValue === null) throw new Error('Rate API response must contain a rate field');
  const rateText = String(rateValue);
  const rateMicros = parseScaledDecimal(rateText, 6, 'rate');
  const units = BigInt(row.eligibleUnits);
  const actualCents = parseScaledDecimal(row.actualPayout, 2, 'actualPayout');
  const expectedCents = (units * rateMicros + 5000n) / 10000n;
  const differenceCents = expectedCents - actualCents;
  return { json: {
    statementId: row.statementId,
    sourceMetadata: row.sourceMetadata,
    platform: row.platform,
    statementPeriod: row.statementPeriod,
    trackName: row.trackName,
    eligibleUnits: row.eligibleUnits,
    territory: row.territory,
    tier: row.tier,
    actualPayout: formatScaled(actualCents, 2),
    rate: rateText,
    rateSource: response.source ?? response.data?.source ?? null,
    expectedPayout: formatScaled(expectedCents, 2),
    difference: formatScaled(differenceCents, 2),
    shortfall: differenceCents > 0n ? formatScaled(differenceCents, 2) : '0.00',
    threshold: formatScaled(thresholdCents, 2),
    isDiscrepancy: differenceCents > thresholdCents
  } };
});

const calculated = $('Code - Calculate Expected Payout').all().map((item) => item.json);
if (calculated.length === 0) throw new Error('No calculated results are available for persistence');
function parseCents(value, allowNegative) {
  const text = String(value);
  const pattern = allowNegative ? /^(-?)(0|[1-9]\d*)\.(\d{2})$/ : /^(0|[1-9]\d*)\.(\d{2})$/;
  const match = pattern.exec(text);
  if (!match) throw new Error('Calculated result contains an invalid money value');
  const negative = allowNegative && match[1] === '-';
  const whole = allowNegative ? match[2] : match[1];
  const fraction = allowNegative ? match[3] : match[2];
  const cents = BigInt(whole) * 100n + BigInt(fraction);
  return negative ? -cents : cents;
}
function formatCents(value) {
  const negative = value < 0n;
  const absolute = negative ? -value : value;
  return (negative ? '-' : '') + (absolute / 100n).toString() + '.' + (absolute % 100n).toString().padStart(2, '0');
}
const groups = new Map();
for (const result of calculated) {
  const sourceFileId = String(result.sourceMetadata?.sourceFileId || '');
  if (!sourceFileId || !Number.isSafeInteger(Number(result.statementId))) throw new Error('Persistence result is missing statement/source identity');
  let group = groups.get(sourceFileId);
  if (!group) {
    group = { statementId: Number(result.statementId), sourceFileId, threshold: result.threshold, totalExpectedCents: 0n, totalActualCents: 0n, totalDifferenceCents: 0n, results: [], discrepancyCount: 0 };
    groups.set(sourceFileId, group);
  }
  if (group.statementId !== Number(result.statementId) || group.threshold !== result.threshold) throw new Error('Inconsistent statement identity or threshold in calculation results');
  group.totalExpectedCents += parseCents(result.expectedPayout, false);
  group.totalActualCents += parseCents(result.actualPayout, false);
  group.totalDifferenceCents += parseCents(result.difference, true);
  if (result.isDiscrepancy === true) group.discrepancyCount++;
  group.results.push({ trackName: result.trackName, eligibleUnits: result.eligibleUnits, territory: result.territory, tier: result.tier, actualPayout: result.actualPayout, rate: result.rate, expectedPayout: result.expectedPayout, difference: result.difference, shortfall: result.shortfall, isDiscrepancy: result.isDiscrepancy });
}
return Array.from(groups.values(), (group) => ({ json: { statementId: group.statementId, sourceFileId: group.sourceFileId, threshold: group.threshold, totalExpected: formatCents(group.totalExpectedCents), totalActual: formatCents(group.totalActualCents), totalDifference: formatCents(group.totalDifferenceCents), discrepancyCount: group.discrepancyCount, results: group.results } }));
